<?php $title = __('Factory Consumption'); ?>
<form method="get" class="toolbar"><input type="hidden" name="r" value="stock/consumption"><input type="date" name="from" value="<?= e($from) ?>"><input type="date" name="to" value="<?= e($to) ?>"><?php if ($batches): ?><select name="batch"><option value=""><?= __('All batches') ?></option><?php foreach ($batches as $b): ?><option value="<?= e($b['batch_no']) ?>" <?= $batch === $b['batch_no'] ? 'selected' : '' ?>><?= e($b['batch_no']) ?></option><?php endforeach; ?></select><?php endif; ?><input name="q" placeholder="<?= e(__('Search batch / details / issue no…')) ?>" value="<?= e($q) ?>"><button class="btn btn-primary" type="submit"><?= __('Filter') ?></button><span style="flex:1"></span><a class="btn btn-primary" href="<?= e(url('stock/consumption/new')) ?>"><?= __('+ Issue to Factory') ?></a></form>
<div class="cards">
  <div class="card amber"><div class="lbl"><?= __('Consumed Today') ?></div><div class="val"><?= qty($todayTotal) ?><span class="muted" style="font-size:14px"> KG</span></div><div class="sub"><?= money($todayValue) ?></div></div>
  <div class="card accent"><div class="lbl"><?= __('Issued Today') ?></div><div class="val"><?= count($p['rows']) ?></div><div class="sub"><?= __('issues this period') ?></div></div>
</div>
<div class="panel"><div class="table-wrap"><table class="tbl"><thead><tr><th><?= __('Date') ?></th><th><?= __('Issue No') ?></th><th><?= __('Batch No') ?></th><th><?= __('Details') ?></th><th class="num"><?= __('Materials') ?></th><th class="num"><?= __('KG') ?></th><th class="num"><?= __('Cost') ?></th><th><?= __('Issued By') ?></th><th><?= __('Approved By') ?></th><th><?= __('Status') ?></th><th></th></tr></thead>
<tbody><?php foreach ($p['rows'] as $r): ?><tr><td><?= date_display($r['date']) ?></td><td class="mono"><?= e($r['issue_no']) ?></td><td class="mono"><?= e($r['batch_no'] ?? '—') ?></td><td><?= e($r['details'] ?? '—') ?></td><td class="num"><?= (int)$r['line_count'] ?></td><td class="num"><?= qty($r['qty_kg']) ?></td><td class="num"><?= money($r['total_cost'], false) ?></td><td><?= e($r['issuer'] ?? '—') ?></td><td><?= e($r['approver'] ?? '—') ?></td>
<td><span class="badge <?= ['posted'=>'green','pending'=>'amber','rejected'=>'red','cancelled'=>'gray'][$r['status']] ?? 'gray' ?>"><?= e(strtoupper($r['status'])) ?></span></td>
<td class="btn-group"><a class="btn btn-outline btn-sm" href="<?= e(url('stock/consumption/' . (int)$r['id'])) ?>"><?= __('View/Print') ?></a><?php if ($r['status'] === 'posted' && Auth::can('journal.reverse')): ?><form method="post" action="<?= e(url('stock/consumption/' . (int)$r['id'] . '/cancel')) ?>" style="display:inline" data-confirm="<?= __('Cancel this consumption? Posted stock will be returned to RM warehouse.') ?>"><?= csrf_field() ?><input type="hidden" name="reason" value="operator cancel"><button class="btn btn-danger btn-sm" type="submit"><?= __('Cancel') ?></button></form><?php endif; ?></td></tr><?php endforeach; ?><?php if (!$p['rows']): ?><tr><td colspan="11" class="muted"><?= __('No factory consumption in this period.') ?></td></tr><?php endif; ?></tbody></table></div>
<?= pager_html($p, 'stock/consumption', ['from' => $from, 'to' => $to, 'q' => $q, 'batch' => $batch]) ?></div>
